import numpy as np
from reference import Task
from scipy.sparse.linalg import eigs, ArpackNoConvergence

N=300; k=5
for maxiter in [10000,15000,20000]:
    print('maxiter', maxiter)
    ok=True
    for seed in range(60):
        A=Task().generate_problem(N, seed)['matrix']; v0=np.ones(N)
        try:
            vals, vecs = eigs(A,k=k,v0=v0,maxiter=maxiter,ncv=20,tol=0,which='LM')
        except ArpackNoConvergence as exc:
            ok=False; print('no converge', seed, exc); break
        vals_ref, vecs_ref = eigs(A,k=k,v0=v0,maxiter=N*200,ncv=20,tol=0,which='LM')
        order=np.argsort(-np.abs(vals)); order_ref=np.argsort(-np.abs(vals_ref))
        for i in range(k):
            v,vr = vecs[:,order[i]], vecs_ref[:,order_ref[i]]
            sim=abs(np.vdot(vr,v)/(np.linalg.norm(vr)*np.linalg.norm(v)))
            if sim<1-1e-6:
                ok=False; print('mis', seed, i, sim); break
        if not ok:
            break
    print('ok', ok)
